// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title IoTDeviceRegistry - Manages IoT device firmware behind reverse proxy
/// @notice Devices register via proxy relay; firmware metadata stored on-chain

struct DeviceConfig {
    address owner;
    address proxyRelay;
    uint256 firmwareVersion;
    bytes32 firmwareHash;
    uint8 trustLevel;
    bool isActive;
    uint256 lastHeartbeat;
    bytes32 configDigest;
}

contract ReverseProxyAuth {
    mapping(address => bool) public authorizedProxies;
    address public admin;

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    modifier onlyProxy() {
        require(authorizedProxies[msg.sender], "Not authorized proxy");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function registerProxy(address proxy) external onlyAdmin {
        authorizedProxies[proxy] = true;
    }
}

contract IoTDeviceRegistry is ReverseProxyAuth {
    mapping(bytes32 => DeviceConfig) public devices;
    mapping(address => bytes32[]) public ownerDevices;

    event DeviceRegistered(bytes32 indexed deviceId, address owner);
    event FirmwareUpdated(bytes32 indexed deviceId, uint256 newVersion);
    event ConfigUpdated(bytes32 indexed deviceId);

    /// @notice Register a new IoT device through the proxy relay
    function registerDevice(
        bytes32 deviceId,
        address deviceOwner,
        bytes32 firmwareHash,
        uint256 firmwareVersion
    ) external onlyProxy {
        require(deviceOwner != address(0), "Invalid owner");
        require(devices[deviceId].owner == address(0), "Device exists");
        devices[deviceId] = DeviceConfig({
            owner: deviceOwner,
            proxyRelay: msg.sender,
            firmwareVersion: firmwareVersion,
            firmwareHash: firmwareHash,
            trustLevel: 1,
            isActive: true,
            lastHeartbeat: block.timestamp,
            configDigest: keccak256(abi.encodePacked(deviceId, firmwareHash))
        });
        ownerDevices[deviceOwner].push(deviceId);
        emit DeviceRegistered(deviceId, deviceOwner);
    }

    /// @notice Batch update device configuration fields
    /// @dev Uses field selector bitmap for gas-efficient partial updates
    /// @param deviceId The device identifier
    /// @param fieldSelector Bitmap: bit0=firmwareVersion, bit1=firmwareHash,
    ///        bit2=trustLevel, bit3=isActive
    /// @param payload ABI-encoded values for selected fields in order
    function updateDeviceConfig(
        bytes32 deviceId,
        uint8 fieldSelector,
        bytes calldata payload
    ) external onlyProxy {
        DeviceConfig storage config = devices[deviceId];
        require(config.owner != address(0), "Device not found");
        require(config.proxyRelay == msg.sender, "Wrong proxy");

        // Only allow operational field updates (bits 0-3)
        require(fieldSelector & 0xF0 == 0, "Cannot modify identity fields");

        uint256 offset = 0;

        if (fieldSelector & 0x01 != 0) {
            config.firmwareVersion = abi.decode(payload[offset:offset+32], (uint256));
            offset += 32;
            emit FirmwareUpdated(deviceId, config.firmwareVersion);
        }
        if (fieldSelector & 0x02 != 0) {
            config.firmwareHash = abi.decode(payload[offset:offset+32], (bytes32));
            offset += 32;
        }
        if (fieldSelector & 0x04 != 0) {
            uint8 newTrust = abi.decode(payload[offset:offset+32], (uint8));
            require(newTrust <= config.trustLevel + 1, "Trust escalation limited");
            config.trustLevel = newTrust;
            offset += 32;
        }
        if (fieldSelector & 0x08 != 0) {
            config.isActive = abi.decode(payload[offset:offset+32], (bool));
            offset += 32;
        }

        config.lastHeartbeat = block.timestamp;
        config.configDigest = keccak256(abi.encodePacked(
            deviceId, config.firmwareHash, config.trustLevel
        ));
        emit ConfigUpdated(deviceId);
    }

    /// @notice Device heartbeat - only updates timestamp
    function heartbeat(bytes32 deviceId) external onlyProxy {
        require(devices[deviceId].proxyRelay == msg.sender, "Wrong proxy");
        devices[deviceId].lastHeartbeat = block.timestamp;
    }

    /// @notice Owner can decommission their device
    function decommission(bytes32 deviceId) external {
        require(devices[deviceId].owner == msg.sender, "Not device owner");
        devices[deviceId].isActive = false;
    }

    /// @notice View function for proxy health check
    function getDeviceStatus(bytes32 deviceId) external view returns (
        bool active,
        uint256 lastSeen,
        uint8 trust
    ) {
        DeviceConfig storage config = devices[deviceId];
        return (config.isActive, config.lastHeartbeat, config.trustLevel);
    }
}
